    put a parallel 8-line immediately on the object's trailing side."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    marker = 2
    bg = counts.most_common(1)[0][0]
    marker_rows = [r for r in range(h) if all(v == marker for v in grid[r])]
    marker_cols = [c for c in range(w) if all(grid[r][c] == marker for r in range(h))]
    obj_color = next(v for v in counts if v != bg and v != marker)
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj_color]
    out = [row[:] for row in grid]

    if marker_rows:
        mr = marker_rows[0]
        minr = min(r for r, c in cells)
        maxr = max(r for r, c in cells)
        if mr < minr:
            dr = mr + 1 - minr
